from __future__ import annotations

import json
from pathlib import Path


TASK_ROOT = Path(__file__).resolve().parent
REPORT_PATH = TASK_ROOT / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_PATH.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_PATH.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def main() -> int:
    try:
        from workflow.overlap_workflow import ExpectedScientificFailure, run_public_observation

        report = run_public_observation()
    except ExpectedScientificFailure as exc:
        return write_report(
            {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "observation": {"workflow_completed": False},
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            1,
        )
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    return write_report(report, 0)


if __name__ == "__main__":
    raise SystemExit(main())

